#!/usr/bin/env python3
import gzip
import os
import re
import sys
from math import comb, lgamma


def open_maybe_gz(path):
    # Galaxy may bind a gzip dataset under a neutral filename, so detect the
    # gzip magic bytes instead of relying on the file extension.
    with open(path, "rb") as probe:
        magic = probe.read(2)
    if magic == b"\x1f\x8b":
        return gzip.open(path, "rt")
    return open(path, "rt")


def parse_quant(path):
    vals = {}
    with open_maybe_gz(path) as fh:
        header = fh.readline().rstrip("\n").split("\t")
        # Salmon output usually Name Length EffectiveLength TPM NumReads
        col = {name: i for i, name in enumerate(header)}
        for line in fh:
            if not line.strip():
                continue
            parts = line.rstrip("\n").split("\t")
            if len(parts) < max(col["TPM"], col["NumReads"]) + 1:
                continue
            name = parts[col["Name"]]
            try:
                tpm = float(parts[col["TPM"]])
                num = float(parts[col["NumReads"]])
            except (ValueError, IndexError):
                continue
            vals[name] = {"tpm": tpm, "num": num}
    return vals


def tx_base(name):
    # Gencode FASTA headers are pipe-delimited: ENST...|ENSG...|...
    return name.split("|")[0].split()[0]


def log_factorial(n):
    return lgamma(n + 1)


def fisher_exact_two_sided(a, b, c, d):
    """Exact two-sided Fisher test for a 2x2 table [[a,b],[c,d]]."""
    row1 = a + b
    row2 = c + d
    col1 = a + c
    col2 = b + d
    total = row1 + row2
    if total == 0:
        return 1.0
